export type OrgsReviewPatGrantRequestsInBulkError = BasicError | ValidationError;

export interface OrgsReviewPatGrantRequestsInBulkParams {
  org: string;
  action: "approve" | "deny" | (string & {});
  patRequestIds?: number[];
  reason?: string | null;
}

/**
 * Approves or denies multiple pending requests to access organization resources via a fine-grained personal access token. Only GitHub Apps can use this endpoint.
 *
 * @param org - The organization name. The name is not case sensitive.
 * @param action - Action to apply to the requests.
 * @param patRequestIds - Unique identifiers of the requests for access via
 *   fine-grained personal access token. Must be formed of between 1 and 100
 *   `pat_request_id` values.
 * @param reason - Reason for approving or denying the requests. Max 1024
 *   characters.
 */
export async function orgsReviewPatGrantRequestsInBulk(
  config: ClientConfig,
  { org, action, patRequestIds, reason }: OrgsReviewPatGrantRequestsInBulkParams,
  requestOptions?: RequestOptions,
): Promise<{ [key: string]: unknown }> {
  if (patRequestIds != null) {
    validateItems("pat_request_ids", patRequestIds, { min: 1, max: 100 });
  }

  if (reason != null) {
    validateLength("reason", reason, { max: 1024 });
  }

  const _resp = await sdkRequest<{ [key: string]: unknown }>({
    method: "POST",
    path: `/orgs/${encodePathSegment(org)}/personal-access-token-requests`,
    operationId: "orgsReviewPatGrantRequestsInBulk",
    errors: {
      "403": "BasicError",
      "404": "BasicError",
      "422": "ValidationError",
      "500": "BasicError",
    },
    responseDecoder: "json",
    ...requestOptions,
    body: {
      action,
      pat_request_ids: patRequestIds,
      reason,
    },
    config,
  });
  return _resp.data;
}
